                if last != -1 and j - last > 1:
                    zeros_between = sum(1 for k in range(last+1, j) if row[k] == 0)
                    if row[j] - row[last] <= zeros_between:
                        # condition violated: output should have been -1
                        assert False, f'row {i} gap condition fails'
                last = j
    # columns
    for j in range(m):
        col = [a[i][j] for i in range(n)]
        last = -1
        for i in range(n):
            if col[i] != 0:
                if last != -1 and i - last > 1:
                    zeros_between = sum(1 for k in range(last+1, i) if col[k] == 0)
                    if col[i] - col[last] <= zeros_between:
                        assert False, f'column {j} gap condition fails'
                last = i

def test_08_constant_shift_when_safe(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = [list(map(int, line.split())) for line in lines[1:1+n]]
    max_val = max(max(row) for row in rows)
    if max_val >= 8000:
        # cannot safely shift, skip
        return
    shifted_rows = []
    for row in rows:
        shifted_rows.append([v+1 if v!=0 else 0 for v in row])
    shifted_input = f'{n} {m}\n' + '\n'.join(' '.join(map(str, r)) for r in shifted_rows)
    out1 = run(x).strip()
    out2 = run(shifted_input).strip()
    if out1 == '-1':
        assert out2 == '-1', f'original impossible but shifted possible'
    else:
        val1 = int(out1)
        val2 = int(out2)
        assert val2 == val1 + n*m, f'shifted output {val2} != original {val1} + {n*m}'

def test_09_corner_consistency(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = [list(map(int, line.split())) for line in lines[1:1+n]]
    tl = rows[0][0]
    tr = rows[0][m-1]
    bl = rows[n-1][0]
    br = rows[n-1][m-1]
    assert tl < br, f'top-left {tl} not less than bottom-right {br}'
    assert tl > 0 and tr > 0 and bl > 0 and br > 0, 'corner zero'
    # in an increasing matrix, top-left is minimal, bottom-right maximal
    # also top-right > top-left and bottom-right > bottom-left etc.
    assert tl < tr, f'top-left {tl} not less than top-right {tr}'
    assert tl < bl, f'top-left {tl} not less than bottom-left {bl}'

def test_10_already_increasing_matrix(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = [list(map(int, line.split())) for line in lines[1:1+n]]
    # check if no zeros and already strictly increasing rows/columns
    has_zero = any(v == 0 for row in a for v in row)
    if has_zero:
        return
    ok = True
    for i in range(n):
        for j in range(m-1):
            if a[i][j] >= a[i][j+1]:
                ok = False
    for j in range(m):
        for i in range(n-1):
            if a[i][j] >= a[i+1][j]:
                ok = False
    if ok:
        out = run(x).strip()
        assert out != '-1', 'valid increasing matrix but output -1'
        total = sum(sum(row) for row in a)
        assert int(out) == total, f'output {out} != sum {total}'

