def test_bounded(run, x):
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    out = run(x).strip().split()
    assert len(out) == n, 'wrong number of lines'
    for i, s in enumerate(out):
        t = int(s)
        assert 0 <= t <= m, f'core {i+1}: output {t} not in [0,{m}]'

def test_nonzero_instruction(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x).strip().split()
    assert len(out) == n
    for i, s in enumerate(out):
        t = int(s)
        if t > 0:
            # instruction for core i+1 at cycle t
            instr_line = lines[i+1].strip().split()
            instr_at_t = int(instr_line[t-1])
            assert 1 <= instr_at_t <= k, f'core {i+1} locks at cycle {t} but instruction is {instr_at_t}'

def test_full_simulation(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    assert len(out) == n
    locked_core = [False] * n
    locked_cell = [False] * k
    for cycle in range(1, m+1):
        # collect writes for this cycle among still-active cores
        writes = {}
        for i in range(n):
            if locked_core[i]:
                continue
            c = instr[i][cycle-1]
            if c == 0:
                continue
            # if cell already locked, this core locks now (spec: any core trying to write a locked cell is immediately locked)
            if locked_cell[c-1]:
                # must have output == cycle
                if out[i] != cycle:
                    assert False, f'core {i+1} should lock at {cycle} because cell {c} already locked, but output says {out[i]}'
                locked_core[i] = True
                continue
            writes.setdefault(c, []).append(i)
        # for each cell with multiple writers, all those writers lock now
        for c, writers in writes.items():
            if len(writers) >= 2:
                for i in writers:
                    if out[i] != cycle:
                        assert False, f'core {i+1} should lock at {cycle} because multiple writers on cell {c}, but output says {out[i]}'
                    locked_core[i] = True
                locked_cell[c-1] = True
            # single writer does not lock (cell remains unlocked) unless it later conflicts; spec says deadlock only when multiple cores try to write at same cycle
        # after processing cycle, check any core with output == cycle is indeed locked now
        for i in range(n):
            if out[i] == cycle:
                if not locked_core[i]:
                    assert False, f'core {i+1} marked locked at {cycle} but simulation did not lock it'
    # after all cycles, cores with output 0 must be unlocked
    for i in range(n):
        if out[i] == 0:
            if locked_core[i]:
                assert False, f'core {i+1} marked unlocked but simulation locked it'
        else:
            if not locked_core[i]:
                assert False, f'core {i+1} marked locked at {out[i]} but simulation unlocked'

def test_core_permutation(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n < 2:
        return  # permutation trivial
    # swap rows 1 and 2 (cores 1 and 2)
    new_lines = [lines[0]] + [lines[2], lines[1]] + lines[3:]
    new_input = '\n'.join(new_lines)
    out_orig = run(x).strip().split()
    out_new = run(new_input).strip().split()
    # inverse permutation of outputs
    perm = [1, 0] + list(range(2, n))
    for i in range(n):
        if out_orig[i] != out_new[perm[i]]:
            assert False, f'core permutation changed output: original {out_orig}, permuted {out_new}'

def test_cell_permutation(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k < 2:
        return  # trivial permutation
    # permute cells: swap 1 and 2
    perm = {1:2, 2:1}
    new_instr = []
    for i in range(1, n+1):
        nums = list(map(int, lines[i].split()))
        new_nums = [perm.get(val, val) for val in nums]
        new_instr.append(' '.join(map(str, new_nums)))
    new_input = f'{n} {m} {k}\n' + '\n'.join(new_instr)
    out_orig = run(x).strip()
    out_new = run(new_input).strip()
    assert out_orig == out_new, f'cell permutation changed output'

def test_dummy_core(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n >= 100:
        return  # cannot add because n ≤ 100 already at max
    # add a core with all zeros
    new_header = f'{n+1} {m} {k}'
