    new_input = '\n'.join(new_lines)
    out_new = run(new_input).strip().split()
    assert len(out_new) == n+1
    # original cores' outputs unchanged
    out_orig = run(x).strip().split()
    for i in range(n):
        if out_orig[i] != out_new[i]:
            assert False, f'adding dummy core changed output for core {i+1}'
    # new core must be 0
    if out_new[n] != '0':
        assert False, f'dummy core should be 0, got {out_new[n]}'

def test_dummy_cell(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k >= 100:
        return
    new_header = f'{n} {m} {k+1}'
    # instructions unchanged (they never refer to cell k+1)
    new_input = new_header + '\n' + '\n'.join(lines[1:])
    out_orig = run(x).strip()
    out_new = run(new_input).strip()
    assert out_orig == out_new, f'adding unused cell changed output'

def test_multiple_active_writers(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    for cycle in range(1, m+1):
        active = [i for i in range(n) if out[i]==0 or out[i] > cycle]
        writes = {}
        for i in active:
            c = instr[i][cycle-1]
            if 1 <= c <= k:
                writes.setdefault(c, []).append(i)
        for c, writers in writes.items():
            if len(writers) >= 2:
                for i in writers:
                    if out[i] != cycle:
                        assert False, f'core {i+1} active at cycle {cycle} writing cell {c} with other writers, but output is {out[i]}'

def test_solo_lock_implies_previous_conflict(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # For each core that locks at some cycle t > 0
    for i in range(n):
        t = out[i]
        if t == 0:
            continue
        c = instr[i][t-1]
        # find if any other core locks at the same t on same cell
        others = [j for j in range(n) if j != i and out[j] == t and instr[j][t-1] == c]
        if not others:
            # solo lock: need earlier conflict on cell c
            conflict_found = False
            for prev in range(1, t):
                writers = [j for j in range(n) if out[j]==0 or out[j] > prev]  # active at prev
                cnt = sum(1 for j in writers if instr[j][prev-1] == c)
                if cnt >= 2:
                    conflict_found = True
                    break
            if not conflict_found:
                # also check if cell already locked before t (due to earlier conflict)
                # simulate locking times
                locked_cell = [False]*k
                for cyc in range(1, t):
                    # collect writes among cores not yet locked at cyc
                    writes = {}
                    for j in range(n):
                        if out[j]==0 or out[j] > cyc:
                            cell = instr[j][cyc-1]
                            if 1 <= cell <= k:
                                writes.setdefault(cell, []).append(j)
                    for cell, writers in writes.items():
                        if len(writers) >= 2:
                            locked_cell[cell-1] = True
                if not locked_cell[c-1]:
                    assert False, f'core {i+1} locks alone at cycle {t} on cell {c} but no earlier conflict on that cell'

def test_output_format(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x)
    out_lines = out.strip().split('\n')
    # must have exactly n lines
    if len(out_lines) != n:
        assert False, f'expected {n} lines, got {len(out_lines)}'
    for i, line in enumerate(out_lines):
        s = line.strip()
        # must be a single integer, no extra whitespace
        if not s.isdigit() and not (s[0]=='-' and s[1:].isdigit()):
            assert False, f'line {i+1}: not an integer: {repr(line)}'
        # ensure no extra spaces around
        if line.strip() != line:
            assert False, f'line {i+1}: extra whitespace'
    # also check no extra characters after last newline
    if out and not out.endswith('\n'):
        # but spec does not forbid missing final newline? we'll accept either
        pass
    # after stripping, we already split, so fine

