    out = list(map(int, run(x).strip().split()))
    for i in range(n):
        t = out[i]
        if t > 0:
            # t is 1‑indexed cycle
            assert 1 <= t <= m
            # instruction at cycle t must be non‑zero (write)
            assert instr[i][t-1] != 0, f"Core {i+1} locked at cycle {t} but instruction is 0"

def test_all_zero_input(run, x):
    lines = x.strip().split('\n')
