    if all(all(v == 0 for v in row) for row in instr):
        out = list(map(int, run(x).strip().split()))
        assert all(v == 0 for v in out), "All instructions zero ⇒ no locks"

def test_swap_cores_symmetry(run, x):
    lines = x.strip().split('\n')
