    swapped_input = '\n'.join(new_lines)
    # run both
    out_orig = list(map(int, run(x).strip().split()))
    out_swap = list(map(int, run(swapped_input).strip().split()))
    # check symmetry
    assert out_swap[i] == out_orig[j], f"Swapped cores: core {i+1} should get core {j+1}'s result"
    assert out_swap[j] == out_orig[i], f"Swapped cores: core {j+1} should get core {i+1}'s result"
    for idx in range(n):
        if idx != i and idx != j:
            assert out_swap[idx] == out_orig[idx], f"Core {idx+1} unchanged after swap"

