def test_append_noop_cycle(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    # build extended input with one extra all‑zero cycle
    new_header = f"{n} {m+1} {k}"
    new_rows = []
    for i in range(1, n+1):
        row = lines[i].split() + ['0']
        new_rows.append(' '.join(row))
