    assert out_ext == out_orig, "Appending a no‑op cycle must not change locking times"

def test_rule_consistency(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    locked_cells = set()
    locked_cores = [False]*n
    for cycle in range(1, m+1):
        # gather active cores and their writes
        writes_to_cell = {}
        for i in range(n):
            if locked_cores[i]:
                continue
            c = instr[i][cycle-1]
            if c == 0:
                continue
            writes_to_cell.setdefault(c, []).append(i)
        # process writes
        for cell, writers in writes_to_cell.items():
            if cell in locked_cells:
                # any writer to a locked cell locks immediately
                for w in writers:
                    # check that output says this core locks now
                    if out[w] != cycle:
                        assert False, f"Core {w+1} writes to locked cell {cell} at cycle {cycle} but output says lock at {out[w]}"
                    locked_cores[w] = True
            else:
                # unlocked cell: if ≥2 writers, all lock
                if len(writers) >= 2:
                    for w in writers:
                        if out[w] != cycle:
                            assert False, f"Core {w+1} conflicts on cell {cell} at cycle {cycle} but output says lock at {out[w]}"
                        locked_cores[w] = True
                    locked_cells.add(cell)
                # if exactly one writer, nothing happens (cell remains unlocked)
    # after simulation, verify cores not locked have output 0
    for i in range(n):
        if not locked_cores[i]:
            assert out[i] == 0, f"Core {i+1} never locked but output says {out[i]}"
        else:
            # locked_cores[i] is True; out[i] should be >0 and ≤m
            assert 1 <= out[i] <= m, f"Core {i+1} locked but output {out[i]} out of range"

def test_cell_lock_persistence(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # infer when each cell becomes locked: earliest cycle where ≥2 writers all lock at that cycle
    cell_lock_cycle = {}
    for cycle in range(1, m+1):
        writers_by_cell = {}
        for i in range(n):
            if out[i] == cycle:  # core locks this cycle
                c = instr[i][cycle-1]
                if c != 0:
                    writers_by_cell.setdefault(c, []).append(i)
        for cell, writers in writers_by_cell.items():
            if len(writers) >= 2 and cell not in cell_lock_cycle:
                cell_lock_cycle[cell] = cycle
    # now check that any later write to a locked cell locks the writer at that later cycle
    for i in range(n):
        t = out[i]
        if t == 0:
            continue
        c = instr[i][t-1]
        if c == 0:
            continue
        # if cell c was locked before cycle t, writer must lock at t
        lock_cycle = cell_lock_cycle.get(c, m+1)
        if lock_cycle < t:
            # cell already locked earlier, so writer must lock at t (already true)
            # but also check that no earlier write to same cell by this core happened without locking
            for prev_cycle in range(1, t):
                if instr[i][prev_cycle-1] == c:
                    # this core wrote to same cell earlier; cell must have been unlocked then
                    assert cell_lock_cycle.get(c, m+1) > prev_cycle, f"Core {i+1} wrote to locked cell {c} at cycle {prev_cycle} but didn't lock until {t}"
        # else cell locked at this same cycle or later, which is fine

def test_no_earlier_lock(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    instr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split()))
    # simulate to find earliest possible lock for each core
    locked_cells = set()
    locked_cores = [False]*n
    for cycle in range(1, m+1):
        writes_to_cell = {}
        for i in range(n):
            if locked_cores[i]:
                continue
            c = instr[i][cycle-1]
            if c == 0:
                continue
            writes_to_cell.setdefault(c, []).append(i)
        # determine which cores would lock this cycle according to rules
        would_lock = set()
        for cell, writers in writes_to_cell.items():
            if cell in locked_cells:
                would_lock.update(writers)
            elif len(writers) >= 2:
                would_lock.update(writers)
                locked_cells.add(cell)
        # update locked_cores for simulation
        for w in would_lock:
            locked_cores[w] = True
        # check each core that actually locks at this cycle: it must be in would_lock
        for i in range(n):
            if out[i] == cycle:
                if i not in would_lock:
                    assert False, f"Core {i+1} locks at cycle {cycle} but rules say it shouldn't"
        # check each core not yet locked by output: it must not be in would_lock
        for i in range(n):
            if out[i] == 0 or out[i] > cycle:
                if i in would_lock:
                    assert False, f"Core {i+1} should have locked at cycle {cycle} but output says {out[i]}"

