def test_bounds(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    occ = sum(1 for v in a if v != 0)
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'
    assert 0 <= val <= occ, f'Output {val} out of bounds [0, {occ}]'

