    pos = {}
    for idx, v in enumerate(a):
        if v == 0:
            continue
        if v not in pos:
            pos[v] = [idx, idx]
        else:
            pos[v][1] = idx
    valid = True
    for v, (l, r) in pos.items():
        for i in range(l, r+1):
            if a[i] != v and a[i] != 0:
                valid = False
                break
        if not valid:
            break
