def test_valid_output(run, x):
    output = run(x).strip()
    assert output in ('Kuro', 'Shiro', 'Katie', 'Draw'), f'Invalid output: {output!r}'

def test_identical_ribbons_draw(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return  # malformed input, but our provided inputs are valid
    if lines[1] == lines[2] == lines[3]:
        output = run(x).strip()
        assert output == 'Draw', f'Identical ribbons must result in Draw, got {output!r}'

def test_length_one_draw(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    if len(lines[1]) == 1 and len(lines[2]) == 1 and len(lines[3]) == 1:
        output = run(x).strip()
        assert output == 'Draw', f'Length‑1 ribbons must result in Draw, got {output!r}'

def test_zero_turns(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    if n != 0:
        return
    # For n = 0, beauty is max character frequency.
    # We cannot know the exact winner, but we can check a consistency bound:
    # the beauty of each ribbon is at most its length.
    # Since the problem statement says the answer is determined by the maximum beauty,
    # and we don't know which cat has it, we just verify that the output is valid.
    output = run(x).strip()
    assert output in ('Kuro', 'Shiro', 'Katie', 'Draw'), f'Invalid output for zero turns: {output!r}'

def test_swap_kuro_shiro(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    # swap Kuro and Shiro lines
    swapped = '\n'.join([lines[0], lines[2], lines[1], lines[3]])
    out_swapped = run(swapped).strip()
    if out_orig == 'Kuro':
        assert out_swapped == 'Shiro', f'Swap Kuro<->Shiro: expected Shiro, got {out_swapped!r}'
    elif out_orig == 'Shiro':
        assert out_swapped == 'Kuro', f'Swap Kuro<->Shiro: expected Kuro, got {out_swapped!r}'
    elif out_orig == 'Katie':
        assert out_swapped == 'Katie', f'Swap Kuro<->Shiro: Katie should stay Katie, got {out_swapped!r}'
    elif out_orig == 'Draw':
        assert out_swapped == 'Draw', f'Swap Kuro<->Shiro: Draw should stay Draw, got {out_swapped!r}'
    else:
        raise AssertionError(f'Invalid original output: {out_orig!r}')

def test_swap_kuro_katie(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    swapped = '\n'.join([lines[0], lines[3], lines[2], lines[1]])
    out_swapped = run(swapped).strip()
    if out_orig == 'Kuro':
        assert out_swapped == 'Katie', f'Swap Kuro<->Katie: expected Katie, got {out_swapped!r}'
    elif out_orig == 'Katie':
        assert out_swapped == 'Kuro', f'Swap Kuro<->Katie: expected Kuro, got {out_swapped!r}'
    elif out_orig == 'Shiro':
        assert out_swapped == 'Shiro', f'Swap Kuro<->Katie: Shiro should stay Shiro, got {out_swapped!r}'
    elif out_orig == 'Draw':
        assert out_swapped == 'Draw', f'Swap Kuro<->Katie: Draw should stay Draw, got {out_swapped!r}'
    else:
        raise AssertionError(f'Invalid original output: {out_orig!r}')

def test_swap_shiro_katie(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    swapped = '\n'.join([lines[0], lines[1], lines[3], lines[2]])
    out_swapped = run(swapped).strip()
    if out_orig == 'Shiro':
        assert out_swapped == 'Katie', f'Swap Shiro<->Katie: expected Katie, got {out_swapped!r}'
    elif out_orig == 'Katie':
        assert out_swapped == 'Shiro', f'Swap Shiro<->Katie: expected Shiro, got {out_swapped!r}'
    elif out_orig == 'Kuro':
        assert out_swapped == 'Kuro', f'Swap Shiro<->Katie: Kuro should stay Kuro, got {out_swapped!r}'
    elif out_orig == 'Draw':
        assert out_swapped == 'Draw', f'Swap Shiro<->Katie: Draw should stay Draw, got {out_swapped!r}'
    else:
        raise AssertionError(f'Invalid original output: {out_orig!r}')

def test_rename_colors_swap(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    # swap 'a'<->'b' and 'A'<->'B' (simple renaming)
    trans = str.maketrans('abAB', 'baBA')
    renamed_lines = [lines[0]] + [s.translate(trans) for s in lines[1:4]]
    renamed_input = '\n'.join(renamed_lines)
    out_renamed = run(renamed_input).strip()
    assert out_renamed == out_orig, f'Color‑swap invariance failed: original {out_orig!r}, renamed {out_renamed!r}'

def test_rename_colors_shift(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    # shift a->b, ..., z->a, A->B, ..., Z->A
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
        if 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 1) % 26 + ord('A'))
        return c  # should not happen
    shifted = [lines[0]] + [''.join(shift_char(ch) for ch in s) for s in lines[1:4]]
    shifted_input = '\n'.join(shifted)
    out_shifted = run(shifted_input).strip()
    assert out_shifted == out_orig, f'Color‑shift invariance failed: original {out_orig!r}, shifted {out_shifted!r}'

def test_reverse_ribbons(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    out_orig = run(x).strip()
    reversed_lines = [lines[0]] + [s[::-1] for s in lines[1:4]]
    reversed_input = '\n'.join(reversed_lines)
    out_reversed = run(reversed_input).strip()
    assert out_reversed == out_orig, f'Reversing invariance failed: original {out_orig!r}, reversed {out_reversed!r}'

