tests_src:
def test_correctness(run, x):
    # Simulate according to specification and compare to program output
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    spec = 3  # initial spectator is Carl (3)
    possible = True
    for w in winners:
        if w == spec:
            possible = False
            break
        spec = 6 - w - spec
    expected = 'YES\n' if possible else 'NO\n'
    assert run(x) == expected, f'Expected {expected!r}, got {run(x)!r}'

def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Invalid output format: {out!r}'

def test_symmetry_1_2(run, x):
    # Build input with 1<->2 swapped
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    swapped = [1 if w==2 else 2 if w==1 else w for w in winners]
    swapped_input = f'{n}\n' + '\n'.join(map(str, swapped)) + '\n'
    assert run(x) == run(swapped_input), 'Output not symmetric under swap 1<->2'

def test_prefix_possible(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    full_out = run(x)
    if full_out == 'YES\n':
        for k in range(1, n+1):
            prefix_input = f'{k}\n' + '\n'.join(map(str, winners[:k])) + '\n'
            assert run(prefix_input) == 'YES\n', f'Prefix of length {k} should be YES'

def test_prefix_impossible(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    for k in range(1, n+1):
        prefix_input = f'{k}\n' + '\n'.join(map(str, winners[:k])) + '\n'
        if run(prefix_input) == 'NO\n':
            assert run(x) == 'NO\n', f'Full sequence should be NO because prefix {k} is NO'
            break

def test_first_winner_not_3(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n >= 1:
        first = int(lines[1])
        if first == 3:
            assert run(x) == 'NO\n', 'First winner 3 must imply NO'

def test_single_game(run, x):
