            assert run(x) == 'YES\n', f'Single game winner {w} must be YES'
        else:
            assert run(x) == 'NO\n', f'Single game winner 3 must be NO'

def test_constant_sequence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    if n >= 1 and all(w == winners[0] for w in winners):
        w = winners[0]
        if w == 1 or w == 2:
            assert run(x) == 'YES\n', f'Constant sequence {w} must be YES'
        else:
            assert run(x) == 'NO\n', f'Constant sequence 3 must be NO'

def test_spectator_consistency(run, x):
    out = run(x)
    if out == 'YES\n':
        lines = x.strip().split('\n')
        n = int(lines[0])
        winners = list(map(int, lines[1:1+n]))
        spec = 3
        for w in winners:
            assert w != spec, f'Winner {w} equals spectator {spec} but output is YES'
            spec = 6 - w - spec

def test_necessary_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    winners = list(map(int, lines[1:1+n]))
    spec = 3
    for w in winners:
        if w == spec:
            assert run(x) == 'NO\n', f'Winner {w} equals spectator {spec} must imply NO'
            break
        spec = 6 - w - spec

