        return
    table = lines[0].strip()
    hand_str = lines[1].strip()
    valid_ranks = set('23456789TJQKA')
    valid_suits = set('DCSH')
    if len(table) != 2 or table[0] not in valid_ranks or table[1] not in valid_suits:
        return
    hand_parts = hand_str.split()
