        if len(card) != 2 or card[0] not in valid_ranks or card[1] not in valid_suits:
            return
        if card in seen:
            return
        seen.add(card)
    if table in seen:
        return
    suit_table = table[1]
    rank_table = table[0]
    # Construct new hand: same suit as table, distinct ranks not equal to rank_table
    all_ranks = list(valid_ranks)
    # Use ranks different from rank_table
    available_ranks = [r for r in all_ranks if r != rank_table]
    if len(available_ranks) < 5:
        return  # not enough distinct ranks (should not happen with 13 ranks)
    new_hand = [available_ranks[i] + suit_table for i in range(5)]
