    {
      "name": "test_bounds",
      "intent": "Parse the output as an integer and assert it is between 1 and n inclusive, as the maximum matching pairs cannot exceed n and must be at least one."
    },
    {
      "name": "test_swap_symmetry",
      "intent": "Run the program on the original input and on the input with the two permutations swapped. The outputs must be equal because the problem is symmetric in a and b."
    },
    {
      "name": "test_shift_b_invariance",
