    },
    {
      "name": "test_brute_force",
      "intent": "Compute the maximum number of matches by trying all shifts d from 0 to n-1: for each d, count matches where a[i] equals b[(i+d) mod n]. Assert the output equals this maximum."
    },
    {
      "name": "test_histogram",
      "intent": "For each value x from 1 to n, compute its positions pos_a[x] in a and pos_b[x] in b. Compute d = (pos_a[x] - pos_b[x]) mod n for each x. Find the maximum frequency of any d. Assert the output equals that maximum frequency."
