    },
    {
      "name": "test_lower_bound_ecc1",
      "intent": "Compute the eccentricity of vertex 1 via BFS (the greatest distance from vertex 1 to any other vertex). The diameter must be at least this eccentricity, so assert that the output is ≥ this computed value."
    },
    {
      "name": "test_upper_bound_ecc1",
      "intent": "Using the same eccentricity of vertex 1, the diameter cannot exceed twice that value (any two vertices are within distance 2·eccentricity(1) via vertex 1). Assert that the output ≤ 2·eccentricity(1)."
