    },
    {
      "name": "test_metamorphic_permutation",
      "intent": "Apply a fixed bijective permutation (e.g., i ↦ ((i*7) mod n)+1) to all vertex numbers. The diameter is invariant under relabeling, so the two outputs must be identical."
    },
    {
      "name": "test_full_recomputation",
      "intent": "Compute the tree diameter independently using the standard two‑BFS method: from any vertex find the farthest vertex u, then from u find the farthest vertex v; the distance between u and v is the diameter. Assert that the program's output equals this computed value."
    },
    {
      "name": "test_path_case",
      "intent": "If the tree is a path (every vertex has degree 1 or 2 and exactly two vertices have degree 1), then the diameter must be n‑1. When the condition holds, assert output == n‑1."
    },
    {
      "name": "test_star_case",
      "intent": "If the tree is a star (one vertex has degree n‑1 and all other vertices have degree 1), then the diameter must be 0 (if n=1), 1 (if n=2), or 2 (if n≥3). When the condition holds, assert the corresponding value."
    },
    {
      "name": "test_lower_bound_multi",
      "intent": "Compute the eccentricities (via BFS) of three vertices: 1, n//2, and n (if they exist). The diameter is at least the maximum of these three eccentricities. Assert that the output ≥ that maximum."
