    },
    {
      "name": "test_symmetry",
      "intent": "Swapping Alice's and Bob's intervals must not change the output. Run the program on (A,B,C,D) and on (C,D,A,B); if the two outputs differ, the test fails."
    },
    {
      "name": "test_translation_invariance_up",
      "intent": "If shifting all times by +1 keeps them within bounds (B+1 <= 100 and D+1 <= 100), then the output for (A+1,B+1,C+1,D+1) must equal the original output. If they differ, the test fails."
    },
    {
      "name": "test_translation_invariance_down",
      "intent": "If shifting all times by -1 keeps them within bounds (A-1 >= 0 and C-1 >= 0), then the output for (A-1,B-1,C-1,D-1) must equal the original output. If they differ, the test fails."
    },
    {
      "name": "test_witness_start",
      "intent": "If the output is positive, then the time t = max(A,C) must lie within both intervals (A <= t < B and C <= t < D). If t fails either inequality, the test fails."
    },
    {
      "name": "test_witness_end",
      "intent": "If the output is positive, then the time t = min(B,D)-1 must lie within both intervals (A <= t < B and C <= t < D). If t fails either inequality, the test fails."
