}

{
  "rationale": "Each test implements the intent from the plan while relying only on properties guaranteed by the specification. Strengthened where needed: for test_non_negative, the spec implies output is a duration (non-negative). test_upper_bound uses min(B-A, D-C) which is derivable from input. test_integer checks output is an integer per spec. test_disjoint_zero uses the disjoint condition from the specification (overlap is max(A,C) < min(B,D), so disjoint is the complement). test_overlap_positive uses the same overlap condition. test_symmetry swaps intervals because the overlap length is symmetric. test_translation_invariance_up/down shifts times while staying within 0-100 bounds (spec allows any values in that range). test_witness_start/end check that if output positive, the start and end times of overlap (max(A,C) and min(B,D)-1) lie within both intervals, which is a necessary condition for a correct overlap length. All tests are property-based, not computing the correct answer. The weakest is test_non_negative because it only catches negative outputs, which are rare.",
  "tests": [
    {
      "name": "test_non_negative",
      "source": "def test_non_negative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0, f'Output {val} is negative.'"
    },
    {
      "name": "test_upper_bound",
      "source": "def test_upper_bound(run, x):
    A, B, C, D = map(int, x.strip().split())
    out = run(x).strip()
    val = int(out)
    max_possible = min(B - A, D - C)
    assert val <= max_possible, f'Output {val} exceeds min individual duration {max_possible}.'"
    },
    {
      "name": "test_integer",
      "source": "def test_integer(run, x):
    out = run(x).strip()
    # Must be an integer: optional leading sign, then digits only
    if out.startswith(('+', '-')):
        rest = out[1:]
    else:
        rest = out
    assert rest.isdigit(), f'Output "{out}" is not an integer.'"
    },
    {
      "name": "test_disjoint_zero",
      "source": "def test_disjoint_zero(run, x):
    A, B, C, D = map(int, x.strip().split())
    out = run(x).strip()
    val = int(out)
    disjoint = (B <= C) or (D <= A)
    if disjoint:
        assert val == 0, f'Intervals are disjoint, output should be 0, got {val}.'"
    },
    {
      "name": "test_overlap_positive",
      "source": "def test_overlap_positive(run, x):
    A, B, C, D = map(int, x.strip().split())
    out = run(x).strip()
    val = int(out)
    overlap = max(A, C) < min(B, D)
    if overlap:
        assert val > 0, f'Intervals overlap, output should be positive, got {val}.'"
    },
    {
      "name": "test_symmetry",
      "source": "def test_symmetry(run, x):
    A, B, C, D = map(int, x.strip().split())
    out1 = run(x).strip()
    swapped_input = f'{C} {D} {A} {B}\n'
    out2 = run(swapped_input).strip()
    assert out1 == out2, f'Output differs when swapping intervals: {out1} vs {out2}.'"
    },
    {
      "name": "test_translation_invariance_up",
      "source": "def test_translation_invariance_up(run, x):
    A, B, C, D = map(int, x.strip().split())
    if B + 1 <= 100 and D + 1 <= 100:
        shifted_input = f'{A+1} {B+1} {C+1} {D+1}\n'
        out1 = run(x).strip()
        out2 = run(shifted_input).strip()
        assert out1 == out2, f'Translation invariance up broken: {out1} vs {out2}.'"
    },
    {
