tests_src:
def test_hello_world(run, x):
    lines = x.splitlines()
    if lines[0] == '1':
        out = run(x).rstrip('\n')
        assert out == 'Hello World'

def test_numeric_output(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        try:
            int(out)
        except ValueError:
            assert False, f'Output {repr(out)} cannot be converted to integer'

def test_sum_bounds(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        val = int(out)
        assert 2 <= val <= 18

def test_commutative(run, x):
    lines = x.splitlines()
    if lines[0] == '2' and len(lines) == 3:
        a, b = lines[1], lines[2]
        # build swapped input
        swapped = '2\n' + b + '\n' + a + '\n'
        out1 = run(x).rstrip('\n')
        out2 = run(swapped).rstrip('\n')
        assert out1 == out2

def test_monotonic_a(run, x):
    lines = x.splitlines()
    if lines[0] == '2' and len(lines) == 3:
        a = int(lines[1])
        b = lines[2]
        if a < 9:
            # original input
            out1 = int(run(x).rstrip('\n'))
            # increased a by 1
            inc_input = f'2\n{a+1}\n{b}\n'
            out2 = int(run(inc_input).rstrip('\n'))
            assert out2 - out1 == 1

def test_monotonic_b(run, x):
    lines = x.splitlines()
    if lines[0] == '2' and len(lines) == 3:
        a = lines[1]
        b = int(lines[2])
        if b < 9:
            out1 = int(run(x).rstrip('\n'))
            inc_input = f'2\n{a}\n{b+1}\n'
            out2 = int(run(inc_input).rstrip('\n'))
            assert out2 - out1 == 1

def test_no_hello_for_two(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        assert out != 'Hello World'

def test_digits_only(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        assert out.isdigit()

def test_no_leading_zero(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        if out:  # non-empty
            assert out[0] != '0'

def test_output_length(run, x):
    lines = x.splitlines()
    if lines[0] == '2':
        out = run(x).rstrip('\n')
        assert len(out) in (1, 2)

