def test_format(run, x):
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    parts = out.split()
    assert len(parts) >= 1, "if not '-1', output must have at least one number"
    nums = []
    for p in parts:
        assert p.isdigit() or (p[0] == '-' and p[1:].isdigit()), f"not an integer: {p}"
        nums.append(int(p))
    for i in range(1, len(nums)):
        assert nums[i] > nums[i-1], "numbers must be strictly increasing"


def test_range(run, x):
    l_str, r_str, k_str = x.strip().split()
    l, r = int(l_str), int(r_str)
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for num in nums:
        assert l <= num <= r, f"{num} not in [{l}, {r}]"


def test_power(run, x):
    _, _, k_str = x.strip().split()
    k = int(k_str)
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for num in nums:
        if num == 1:
            continue  # k^0 is always a power of k
        n = num
        while n % k == 0:
            n //= k
        assert n == 1, f"{num} is not a power of {k}"


def test_consecutive(run, x):
    _, _, k_str = x.strip().split()
    k = int(k_str)
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for i in range(1, len(nums)):
        assert nums[i] == nums[i-1] * k, f"powers are not consecutive: {nums[i-1]}, {nums[i]}"


def test_lower_bound(run, x):
    l_str, r_str, k_str = x.strip().split()
    l, k = int(l_str), int(k_str)
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    first = nums[0]
    if first == 1:
        assert l <= 1  # always true because l ≥ 1
    else:
        assert first // k < l, f"smaller power {first//k} might be in range"


def test_upper_bound(run, x):
    l_str, r_str, k_str = x.strip().split()
    r, k = int(r_str), int(k_str)
    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    last = nums[-1]
    # Use Python's big ints, no overflow issue
    assert last * k > r, f"larger power {last*k} might be in range"


def test_scale_up(run, x):
    l_str, r_str, k_str = x.strip().split()
    l, r, k = int(l_str), int(r_str), int(k_str)
    if r * k > 10**18:
        return  # transformed input would be invalid
    out1 = run(x).rstrip('\n')
    transformed_input = f"{l*k} {r*k} {k}\n"
    out2 = run(transformed_input).rstrip('\n')
    if out1 == '-1':
        assert out2 == '-1', f"original empty, scaled should be empty"
    else:
        nums1 = list(map(int, out1.split()))
        nums2 = list(map(int, out2.split()))
        assert len(nums1) == len(nums2), f"length mismatch after scaling up"
        for a, b in zip(nums1, nums2):
            assert b == a * k, f"scaled mismatch: {b} != {a} * {k}"


def test_scale_down(run, x):
    l_str, r_str, k_str = x.strip().split()
    l, r, k = int(l_str), int(r_str), int(k_str)
    if l % k != 0 or r % k != 0:
        return  # transformed input would not be integer
    out1 = run(x).rstrip('\n')
    transformed_input = f"{l//k} {r//k} {k}\n"
    out2 = run(transformed_input).rstrip('\n')
    if out1 == '-1':
        assert out2 == '-1', f"original empty, scaled should be empty"
    else:
        nums1 = list(map(int, out1.split()))
        nums2 = list(map(int, out2.split()))
        assert len(nums1) == len(nums2), f"length mismatch after scaling down"
