    out = run(x).rstrip('\n')
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    # compute max possible count: start at 1, multiply by k until > r
    cnt = 0
    val = 1
    while val <= r:
        cnt += 1
        if val > r // k:  # avoid overflow
