tests_src:
def test_non_negative(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())
    val = int(out)
    assert val >= 0

def test_upper_bound(run, x):
    # maximum distance between two letters is 13 (e.g., 'a' to 'n')
    s = x.strip()
    L = len(s)
    out = run(x).strip()
    val = int(out)
    assert val <= 13 * L

def test_lower_bound_last(run, x):
    s = x.strip()
    last = s[-1]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    min_needed = dist('a', last)
    out = run(x).strip()
    val = int(out)
    assert val >= min_needed

def test_prepend_a(run, x):
    s = x.strip()
    if len(s) >= 100:
        return   # cannot modify because string length limit is 100
    new_s = 'a' + s
    out1 = run(x).strip()
    out2 = run(new_s + '\n').strip()
    # prepending 'a' (starting at 'a') should not change total rotations
    assert out1 == out2

def test_append_a(run, x):
    s = x.strip()
    if len(s) >= 100:
        return
    last = s[-1]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    expected_extra = dist(last, 'a')
    out1 = run(x).strip()
    out2 = run(s + 'a\n').strip()
    assert int(out2) == int(out1) + expected_extra

def test_all_same(run, x):
    s = x.strip()
    if len(set(s)) != 1:
        return   # only test when all characters are identical
    ch = s[0]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    expected = dist('a', ch)
    out = run(x).strip()
    assert int(out) == expected

def test_single_char(run, x):
    s = x.strip()
    if len(s) != 1:
        return
    ch = s[0]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    expected = dist('a', ch)
    out = run(x).strip()
    assert int(out) == expected

def test_two_char(run, x):
    s = x.strip()
    if len(s) < 2:
        return
    first_two = s[:2]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    expected = dist('a', first_two[0]) + dist(first_two[0], first_two[1])
    out = run(first_two + '\n').strip()
    assert int(out) == expected

def test_three_char_bounds(run, x):
    s = x.strip()
    if len(s) < 3:
        return
    first_three = s[:3]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    direct = dist('a', first_three[2])
    pairwise = dist('a', first_three[0]) + dist(first_three[0], first_three[1]) + dist(first_three[1], first_three[2])
    out = run(first_three + '\n').strip()
    val = int(out)
    assert direct <= val <= pairwise

def test_append_aa(run, x):
    s = x.strip()
    if len(s) >= 99:
        return
    last = s[-1]
    def dist(a,b):
        diff = abs(ord(a)-ord(b))
        return min(diff, 26-diff)
    expected_extra = dist(last, 'a')
    out1 = run(x).strip()
    out2 = run(s + 'aa\n').strip()
    assert int(out2) == int(out1) + expected_extra

