def test_output_format(run, x):
    out = run(x)
    assert out in ("A\n", "B\n", "C\n", "D\n")

def test_great_if_not_c(run, x):
    out = run(x).strip()
    if out == "C":
        return
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    chosen = ord(out) - ord('A')
    chosen_len = lengths[chosen]
    other_lens = lengths[:chosen] + lengths[chosen+1:]
    # check great condition: at least twice shorter than all others OR at least twice longer
    if all(chosen_len * 2 <= other for other in other_lens):
        return
    if all(chosen_len >= 2 * other for other in other_lens):
        return
    assert False, f"Chosen {out} with length {chosen_len} is not great among {lengths}"

def test_c_if_not_one_great(run, x):
    out = run(x).strip()
    if out != "C":
        return
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    greats = []
    for i, L in enumerate(lengths):
        others = lengths[:i] + lengths[i+1:]
        if all(L * 2 <= o for o in others) or all(L >= 2 * o for o in others):
            greats.append(i)
    assert len(greats) != 1, f"Exactly one great choice ({chr(ord('A')+greats[0])}) but output is C"

def test_swap_equal_lengths(run, x):
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    # find any pair with equal lengths
    for i in range(4):
        for j in range(i+1, 4):
            if lengths[i] == lengths[j]:
                # swap descriptions, keeping prefixes in order
                pref_i, desc_i = lines[i].split('.', 1)
                pref_j, desc_j = lines[j].split('.', 1)
                new_lines = lines.copy()
                new_lines[i] = pref_i + '.' + desc_j
                new_lines[j] = pref_j + '.' + desc_i
                new_input = '\n'.join(new_lines) + '\n'
                out1 = run(x).strip()
                out2 = run(new_input).strip()
                assert out1 == out2, f"Swapping equal-length {chr(ord('A')+i)} and {chr(ord('A')+j)} changed answer"
                return  # one swap is enough for the property
    # if no equal lengths, test passes trivially
    return

def test_scaling_invariance(run, x):
    lines = x.strip().split('\n')
    # check each length <= 50 (so that duplication stays within 100 chars)
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    if any(L > 50 for L in lengths):
        return  # cannot safely duplicate
    new_lines = []
    for line in lines:
        pref, desc = line.split('.', 1)
        new_lines.append(pref + '.' + desc + desc)
    new_input = '\n'.join(new_lines) + '\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f"Doubling all descriptions changed answer"

def test_no_great_implies_c(run, x):
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    greats = []
    for i, L in enumerate(lengths):
        others = lengths[:i] + lengths[i+1:]
        if all(L * 2 <= o for o in others) or all(L >= 2 * o for o in others):
            greats.append(i)
    if len(greats) == 0:
        assert run(x).strip() == "C", f"No great choice but output is not C"

def test_one_great_implies_choice(run, x):
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    greats = []
    for i, L in enumerate(lengths):
        others = lengths[:i] + lengths[i+1:]
        if all(L * 2 <= o for o in others) or all(L >= 2 * o for o in others):
            greats.append(i)
    if len(greats) == 1:
        expected = chr(ord('A') + greats[0])
        assert run(x).strip() == expected, f"Exactly one great choice {expected} but output is different"

def test_two_greats_implies_c(run, x):
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    greats = []
    for i, L in enumerate(lengths):
        others = lengths[:i] + lengths[i+1:]
        if all(L * 2 <= o for o in others) or all(L >= 2 * o for o in others):
            greats.append(i)
    if len(greats) >= 2:
        assert run(x).strip() == "C", f"At least two great choices {[chr(ord('A')+g) for g in greats]} but output is not C"

def test_output_length(run, x):
    out = run(x)
    assert len(out) == 2 and out[0] in "ABCD" and out[1] == "\n", f"Output format invalid: {repr(out)}"

def test_consistent_with_lengths(run, x):
    lines = x.strip().split('\n')
    lengths = [len(line.split('.', 1)[1]) for line in lines]
    greats = []
    for i, L in enumerate(lengths):
        others = lengths[:i] + lengths[i+1:]
        if all(L * 2 <= o for o in others) or all(L >= 2 * o for o in others):
            greats.append(i)
    if len(greats) == 1:
        expected = chr(ord('A') + greats[0])
    else:
        expected = "C"
    assert run(x).strip() == expected, f"Output inconsistent with lengths {lengths}: expected {expected}"

